files.entry.sh:
#!/bin/bash
set -e
cat > /etc/zabbix/zabbix_agentd.conf <<EOF
Server=${ZBX_SERVER_HOST:-127.0.0.1}
ServerActive=${ZBX_SERVER_ACTIVE:-127.0.0.1}
Hostname=${ZBX_HOSTNAME:-$(hostname)}
LogFile=/tmp/zabbix_agentd.log
PidFile=/tmp/zabbix_agentd.pid
${ZBX_PASSIVE_ALLOW:+AllowRoot=1}
EOF
exec zabbix_agentd -f -c /etc/zabbix/zabbix_agentd.conf
